-- Makaman price lists — full re-import from the cleaned source.
--
-- Generated from makaman_price_lists_5.sql (2,610 rows). Three things the source file
-- could not know about this database, all corrected here:
--
--   1. client_id is a uuid, not the integers 1-5 the source used. The real ids are
--      substituted below, and WAHA 1 + WAHA 2 both map to the single Waha Oil Company
--      record rather than two clients.
--   2. TRUNCATE ... CASCADE is replaced with a plain DELETE inside a transaction.
--      Nothing references price_list_items (checked), but CASCADE is a blunt instrument
--      to point at a live database and DELETE rolls back cleanly if anything fails.
--   3. The source CREATE TABLE is dropped entirely -- the real table already exists with
--      the right shape, and running it could only ever be a no-op or a conflict.
--
-- Sirte is LYD; every other client is USD. That is already correct in the source and is
-- preserved here rather than defaulted.
--
-- Safe to re-run: the whole thing is one transaction, so a failure anywhere leaves the
-- existing price lists exactly as they were.

begin;

delete from price_list_items;


-- WAHA 1 Price List — 228 rows (USD)
insert into price_list_items (client_id,item_number,description,uom,unit_cost,unit_cost_additional,has_valid_code,source_sheet,currency)
